def get_bearer_token() -> str:
    return jwt.encode({}, env.AGENT_AUTH_TOKEN_SECRET, algorithm="HS256")


def _create_microsecond_timestamp(occurred_at: float) -> str:
    # Note - timezone is not terribly important here because as long as we are focusing on monotonic timestamps
    # the timestamp value itself will be hilariously imprecise (i.e set in the year 7000). So we don't sweat the
    # timezone not being accurate
    return datetime.fromtimestamp(occurred_at).astimezone().isoformat()


@tenacity.retry(
    stop=stop_after_attempt(env.MAX_API_RETRIES),
    wait=wait_exponential_jitter(),
    before_sleep=log_retry,
)
async def get_candidate_profile(
    ctx: JobContext,
) -> Optional[profile_v1.CandidateProfileResponse]:
    params = {"roomName": ctx.job.room.name}
    caller_param = urlencode(params)

    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(
                f"{env.JOBS_API_HOST}/api/profiles?{caller_param}",
                headers={
                    "Content-Type": "application/json",
                    "Authorization": "Bearer " + get_bearer_token(),
                },
            ) as response:
                if response.status == 404:
                    logger.info(
                        f"Candidate profile not found for {caller_param}",
                        extra={"job_id": ctx.job.id, "room_name": ctx.job.room.name},
                    )
                    return None
                response.raise_for_status()
                data = await response.json()
                if data.get("modelVersion") == "v1":
                    return profile_v1.load_candidate_profile_response(data)
                else:
                    raise Exception("Unsupported modelVersion")
    except Exception as e:
        logger.error(
            f"Failed to fetch candidate profile: {e}",
            extra={"job_id": ctx.job.id, "room_name": ctx.job.room.name},
        )
        return None


